(resolve, reject) => {
      const child = spawn(cmd, argv, { ...options, stdio:['ignore','pipe','pipe'] });
      let timer;
      let bytes = 0, exceeded = false;
      function forward(stream, destination) {
        stream.on('data', chunk => {
          bytes += chunk.length;
          if (byteLimit !== undefined && bytes > byteLimit) {
            exceeded = true;
            child.kill('SIGKILL');
            return;
          }
          destination.write(chunk);
        });
      }
      forward(child.stdout, process.stdout);
      forward(child.stderr, process.stderr);
      if(timeoutMs !== undefined) timer=setTimeout(() => child.kill('SIGKILL'), timeoutMs);
      child.once('error',reject);
      child.once('close',(code,signal)=>{clearTimeout(timer);resolve({code,signal,exceeded});});
    }

