function parseComment(body){
  const state=JSON.parse(between(body,STATE_START,STATE_END));
  validateState(state);
  const id=identity(state.source_comment_id,state.definition.nonce);
  if(body.split(id).length!==2)throw Error('Procedure identity missing or duplicated');
  const bot=parsePane(body,BOT_START,BOT_END);
  if(JSON.stringify(bot)!==JSON.stringify(botProjection(state)))throw Error('Bot instruction panel differs from state');
  return {state,bot,answer:parsePane(body,ANSWER_START,ANSWER_END)};
}

function validateLibrary(c,s,schema){
 if(c?.schema!=='issuestack.semantic-operator.contract.v1'||c.version!==1||
 s?.schema!=='issuestack.semantic-operator.fewshots.v1'||s.version!==1)throw Error('Unsupported contract/examples versions');
 if(!schema?.$defs?.semantic_proposal||!schema?.$defs?.checkpoint)throw Error('Missing output schemas');
 if(c.lifecycle?.state_machine?.length!==9||c.lifecycle.state_machine.some((x,i)=>x.id!=='P'+i||!x.decision||!x.on_no))throw Error('Incomplete procedure');
 if(c.budgets?.max_chore_passes_per_command!==1||c.budgets?.stop_on_new_primary_command!==true||
 c.budgets?.max_evidence_units<1||c.budgets?.max_evidence_units>32||
 c.budgets?.max_tool_calls<1||c.budgets?.max_tool_calls>40||
 c.budgets?.max_proposals<1||c.budgets?.max_proposals>30||
 c.idempotency?.no_chore_recursion!==true)throw Error('Unsafe/unbounded budget');
 if(!Array.isArray(c.ontology?.concepts)||c.ontology.concepts.length!==9)throw Error('Missing ontology');
 const ids=new Set();
 for(const concept of c.ontology.concepts){string(concept.id,'concept');if(ids.has(concept.id))throw Error('Duplicate concept');ids.add(concept.id);
  for(const field of ['definition','inclusion','exclusion'])string(concept[field],field);
  const payload=schema.$defs['payload_'+concept.id];if(!payload||!eq(payload.required,concept.required_payload_fields))throw Error('Payload contract mismatch '+concept.id);
 }
 if(!Array.isArray(c.operations)||!eq(c.operations.map(x=>x.id),OPS))throw Error('Incomplete operation set');
 for(const op of c.operations)for(const f of ['definition','precondition','forbidden_when'])string(op[f],op.id+' '+f);
 if(c.chore_catalog?.length!==7||c.chore_catalog.some((x,i)=>x.id!=='SC0'+(i+1)||x.version!==1||!x.procedure||!x.acceptance))throw Error('Invalid chore ordering');
 for(const [kind,entries,set]of [['concept',s.concepts,ids],['operation',s.operations,new Set(OPS)]]){
  if(!Array.isArray(entries)||entries.length!==set.size)throw Error('Missing '+kind+' examples');
  const found=new Set();
  for(const item of entries){const id=item.concept||item.operation;if(!set.has(id)||found.has(id))throw Error('Unknown or duplicated '+kind+' example');found.add(id);
   if(item.examples?.length!==3||!eq(item.examples.map(e=>e.kind),['positive','boundary','negative']))throw Error('Must have three contrastive examples '+id);
   for(const e of item.examples){string(e.input,'example input');string(e.why,'example reason');
    if(e.fixture_provenance!=='synthetic_training_demonstration_not_empirical_issue_stack_evidence')throw Error('Examples must disclose hypothetical provenance');
    if(kind==='concept'){if(e.expected?.record_type!==id||!OPS.includes(e.expected?.operation)||!e.decision_boundary)throw Error('Invalid expected concept ruling');}
    else if(!OPS.includes(e.expected_operation)||!e.contrast)throw Error('Invalid operation ruling');
   }
  }
 }
 if(!Array.isArray(s.end_to_end)||s.end_to_end.length<3||s.end_to_end.some(e=>e.steps?.length<7||!e.output))throw Error('Incomplete worked procedures');
 return true;
}

function main() {
  const [input,output,...rest]=process.argv.slice(2);
  if(!input||!output) throw Error('Usage: node src/compare.js INPUT.wav OUTPUT.json [--model-dir DIRECTORY]');
  if(rest.length!==0 && (rest.length!==2 || rest[0]!=='--model-dir')) throw Error('Invalid arguments');
  const result=run(input,{modelDir:rest.length===2?rest[1]:(process.env.MODEL_DIR||'/opt/models')});
  mkdirSync(dirname(resolve(output)),{recursive:true});
  writeFileSync(resolve(output),JSON.stringify(result,null,2)+'\n',{mode:0o600});
  console.log(JSON.stringify({output,modelStatus:result.models.truthDetection.status}));
}

function decodeConversation(table) {
  const at = i => Number.isInteger(i) && i >= 0 && i < table.length ? table[i] : undefined;
  function ref(objectIndex, name) {
    const o = at(objectIndex);
    if (!o || Array.isArray(o) || typeof o !== "object") return undefined;
    for (const [key, value] of Object.entries(o)) {
      if (/^_\d+$/.test(key) && at(Number(key.slice(1))) === name) return value;
    }
    return undefined;
  }
  const get = (objectIndex, name) => at(ref(objectIndex, name));

  // The script's message mapping and current node define the visible branch.
  // Do not shortcut via linear_conversation; reconstruct from parent references.
  const pending = [{index: 0, depth: 0}], explored = new Set();
  let root;
  for (let p = 0; p < pending.length; p++) {
    const {index, depth} = pending[p];
    if (explored.has(index) || depth > 12 || index < 0) continue;
    explored.add(index);
    if (ref(index, "mapping") !== undefined && ref(index, "current_node") !== undefined) {
      root = index;
      break;
    }
    const o = at(index);
    if (!o || Array.isArray(o) || typeof o !== "object") continue;
    for (const [key, value] of Object.entries(o)) {
      if (!/^_\d+$/.test(key) || !Number.isInteger(value)) continue;
      if (at(Number(key.slice(1))) === "linear_conversation") continue;
      if (at(value) !== null && typeof at(value) === "object") pending.push({index: value, depth: depth + 1});
    }
  }
  if (root === undefined) throw new Error("Missing message map in serialized HTML");
  const mapping = get(root, "mapping");
  const currentId = get(root, "current_node");
  if (!mapping || Array.isArray(mapping) || typeof mapping !== "object" || typeof currentId !== "string") {
    throw new Error("Invalid conversation message map");
  }

  const byId = new Map();
  for (const [key, nodeIndex] of Object.entries(mapping)) {
    if (/^_\d+$/.test(key)) {
      const id = at(Number(key.slice(1)));
      if (typeof id === "string") byId.set(id, nodeIndex);
    }
  }
  if (!byId.has(currentId)) throw new Error("Current message node not found");

  const chain = [], visited = new Set();
  let cursor = currentId;
  while (cursor != null) {
    if (visited.has(cursor)) throw new Error("Cyclic message parent link");
    visited.add(cursor);
    const node = byId.get(cursor);
    if (node === undefined) throw new Error("Missing parent message " + cursor);
    chain.push(node);
    cursor = get(node, "parent");
  }
  chain.reverse();

  const messages = [], counts = {user: 0, commentary: 0, final: 0};
  for (const node of chain) {
    const message = ref(node, "message");
    if (message === undefined || at(message) == null) continue;
    const role = get(ref(message, "author"), "role");
    const channel = get(message, "channel") ?? null;
    let countKey;
    if (role === "user") countKey = "user";
    else if (role === "assistant" && channel === "commentary") countKey = "commentary";
    else if (role === "assistant" && channel === "final") countKey = "final";
    else continue;

    const parts = get(ref(message, "content"), "parts");
    if (!Array.isArray(parts)) continue;
    const text = parts.map(at).filter(value => typeof value === "string").join("\n").trimEnd();
    if (!text.trim()) continue;
    messages.push({role, channel: role === "user" ? null : channel, text});
    counts[countKey] += 1;
  }
  if (!messages.length || !counts.user || !counts.final) {
    throw new Error("No complete user/assistant conversation recovered");
  }
  if (messages.length !== counts.user + counts.commentary + counts.final) throw new Error("Role totals mismatch");
  return {messages, counts, chainCount: chain.length};
}

function renderMarkdown(messages) {
  const turns = [];
  let active = [];
  for (const m of messages) {
    if (m.role === "user" && active.length) {
      turns.push(active.join("

"));
      active = [];
    }
    if (m.role === "user") active.push("**You**

" + quoteMarkdown(m.text));
    else if (m.channel === "commentary") active.push("**Assistant · Commentary**

" + quoteMarkdown(m.text));
    else active.push("**Assistant**

" + m.text);
  }
  if (active.length) turns.push(active.join("

"));
  return "# Conversation

" + turns.join("

---

") + "
";
}

async function enumerate({github, context}) {
  if (context.repo.owner + '/' + context.repo.repo !== REPOSITORY)
    throw new Error('Unexpected repository');
  if (context.actor !== context.repo.owner)
    throw new Error('Only repository owner-authored instructions may execute');
  if (context.eventName === 'workflow_dispatch') {
    return [validatePath(context.payload.inputs?.instruction_file)];
  }
  if (context.eventName !== 'push' || context.ref !== 'refs/heads/main')
    throw new Error('Unsupported workflow trigger or branch');
  const before = context.payload.before;
  if (!/^[0-9a-f]{40}$/i.test(before) || /^0+$/.test(before))
    throw new Error('Cannot safely inventory changed instructions from this push');
  const response = await github.rest.repos.compareCommits({
    ...context.repo, base: before, head: context.sha, per_page: 300
  });
  const files = response.data.files || [];
  if (files.length >= 300)
    throw new Error('Comparison may be truncated; refusing partial instruction execution');
  return [...new Set(files.filter(f =>
    ['added', 'modified', 'renamed'].includes(f.status) &&
    f.filename.startsWith(INSTRUCTIONS) && f.filename.endsWith('.json'))
    .map(f => validatePath(f.filename)))].sort();
}

