function evaluateCondition(state, condition) {
  if (/^\$\{[A-Za-z_$][\w$]*\}$/.test(condition)) {
    const value = resolvePath(state, condition);
    if (typeof value !== "boolean") throw new Error("Boolean decision requires a Boolean value.");
    return value;
  }
  const match = condition.match(/^(\$\{[A-Za-z_$][\w$]*\}(?:\.length)?)\s*(=|!=|>)\s*(.+)$/);
  if (!match) throw new Error("Unsupported Boolean expression: " + condition);
  const actual = resolvePath(state, match[1]);
  const expected = JSON.parse(match[3]);
  if (match[2] === "=") return actual === expected;
  if (match[2] === "!=") return actual !== expected;
  return actual > expected;
}

function resolveValue(scope, value) {
  if (typeof value !== "string" || !value.startsWith("${")) return structuredClone(value);
  const increment = value.match(/^(\$\{[A-Za-z_$][\w$]*\})\s*\+\s*(\d+)$/);
  if (increment) {
    const current = resolvePath(scope, increment[1]);
    if (!Number.isInteger(current)) throw new Error("Counter must be an integer.");
    return current + Number(increment[2]);
  }
  return structuredClone(resolvePath(scope, value));
}

function changesBetween(before,after,path=''){
 if(JSON.stringify(before)===JSON.stringify(after))return [];
 const object=x=>x&&typeof x==='object'&&!Array.isArray(x);
 if(Array.isArray(before)&&Array.isArray(after)&&before.length<=after.length&&before.every((v,i)=>JSON.stringify(v)===JSON.stringify(after[i])))return [{operation:'append',path,values:structuredClone(after.slice(before.length))}];
 if(object(before)&&object(after)){
  const changes=[];
  for(const key of new Set([...Object.keys(before),...Object.keys(after)])){
   const child=path+'/'+key.replaceAll('~','~0').replaceAll('/','~1');
   if(!Object.hasOwn(after,key))changes.push({operation:'delete',path:child});
   else if(!Object.hasOwn(before,key))changes.push({operation:'set',path:child,value:structuredClone(after[key])});
   else changes.push(...changesBetween(before[key],after[key],child));
  }
  return changes;
 }
 return [{operation:'set',path,value:structuredClone(after)}];
}

function writeDialogues(batch, outputPath) {
  const dialogues = extractDialogues(batch);
  if (fs.existsSync(outputPath) && (!fs.statSync(outputPath).isDirectory() || fs.readdirSync(outputPath).length > 0)) {
    throw new Error(`Output directory must be new or empty: ${outputPath}`);
  }
  fs.mkdirSync(outputPath, {recursive: true});

  for (const dialogue of dialogues) {
    const conversation = Array.isArray(batch) ? batch[dialogue.conversationIndex] : batch;
    const id = conversation.id ?? conversation.conversation_id ?? `conversation-${dialogue.conversationIndex + 1}`;
    const filename = `${String(dialogue.conversationIndex + 1).padStart(4, '0')}-${safeName(id)}-branch-${String(dialogue.branchIndex + 1).padStart(4, '0')}.txt`;
    fs.writeFileSync(path.join(outputPath, filename), dialogue.text + '\n', {encoding: 'utf8', flag: 'wx'});
  }
  return dialogues.length;
}

