function main() {
  const projectNames = JSON.parse(fs.readFileSync(feedFile, "utf8"));
  if (!Array.isArray(projectNames)) {
    throw new Error("projectnames.json must be a JSON array.");
  }

  // Validate the entire feed before changing the filesystem.
  const seen = new Set();
  for (const projectName of projectNames) {
    const dirName = folderNameFor(projectName);
    const key = dirName.normalize("NFC").toLowerCase();
    if (seen.has(key)) {
      throw new Error("Duplicate or colliding directory name: " + dirName);
    }
    seen.add(key);
  }

  fs.mkdirSync(projectsDir, { recursive: true });
  let created = 0;
  let existing = 0;

  // The JSON array is the feed for this iterator.
  for (const projectName of projectNames) {
    const folderName = folderNameFor(projectName);
    const target = path.join(projectsDir, folderName);
    const alreadyExists = fs.existsSync(target);
    fs.mkdirSync(target, { recursive: true });

    // Git does not track empty directories; never overwrite an existing marker.
    const marker = path.join(target, ".gitkeep");
    if (!fs.existsSync(marker)) fs.writeFileSync(marker, "", { flag: "wx" });

    if (alreadyExists) existing++;
    else created++;
    console.log((alreadyExists ? "EXISTS " : "CREATED ") + folderName);
  }

  console.log(JSON.stringify({ processed: projectNames.length, created, existing }));
}

function resolvePath(baseDir, candidatePath) {
  if (!candidatePath || typeof candidatePath !== 'string') return null;
  return path.isAbsolute(candidatePath) ? candidatePath : path.resolve(baseDir, candidatePath);
}

function semanticAt(raw, slot) {
  if (slot === -5 || slot === -1) return undefined;
  if (slot === -2) return NaN;
  if (slot === -3) return Infinity;
  if (slot === -4) return -Infinity;
  if (typeof slot !== 'number' || slot < 0 || slot >= raw.length) return slot;
  return raw[slot];
}

function decodeSlot(slot) {
    if (slot === -5 || slot === -1) return undefined;
    if (slot === -2) return NaN;
    if (slot === -3) return Infinity;
    if (slot === -4) return -Infinity;
    if (typeof slot !== 'number' || slot < 0 || slot >= raw.length) return slot;
    if (cache.has(slot)) return cache.get(slot);

    const item = raw[slot];
    if (item === null || typeof item !== 'object') {
      cache.set(slot, item);
      return item;
    }

    if (Array.isArray(item)) {
      if (item.length === 2 && item[0] === 'P') {
        const promiseMarker = { __promise: item[1] };
        cache.set(slot, promiseMarker);
        return promiseMarker;
      }
      if (item.length === 2 && item[0] === 'D') {
        const date = new Date(item[1]);
        cache.set(slot, date);
        return date;
      }
      const array = [];
      cache.set(slot, array);
      for (const value of item) array.push(decodeSlot(value));
      return array;
    }

    const object = {};
    cache.set(slot, object);
    for (const [key, valueSlot] of Object.entries(item)) {
      const propertyName = key.startsWith('_') ? raw[Number(key.slice(1))] : key;
      const propertyValue = decodeSlot(valueSlot);
      if (propertyName !== undefined && propertyValue !== undefined) {
        object[propertyName] = propertyValue;
      }
    }
    return object;
  }

function filePredicates(relativePath) {
  const absolute = resolveRepoFile(relativePath);
  const exists = fs.existsSync(absolute) && fs.statSync(absolute).isFile();
  let parsed = null;
  let raw = '';
  let isJson = false;
  let isMinified = false;
  let isFlattened = false;

  if (exists) {
    raw = fs.readFileSync(absolute, 'utf8');
    try {
      parsed = JSON.parse(raw);
      isJson = true;
      isMinified = raw.trim() === JSON.stringify(parsed);
    } catch {
      isJson = false;
    }
  }

  if (exists && isJson) {
    try {
      const output = execFileSync(process.execPath, [flattenCheckerPath, absolute], { encoding: 'utf8' });
      isFlattened = JSON.parse(output).valid === true;
    } catch {
      isFlattened = false;
    }
  }

  return {
    file_does_exist_$bool: exists,
    file_is_json_$bool: isJson,
    file_is_minified_$bool: isMinified,
    file_is_flattened_$bool: isFlattened,
    parsed
  };
}

function terminalIsEmptyContainer(value) {
  const terminal = terminalNode(value);
  if (Array.isArray(terminal)) return terminal.length === 0;
