async function dispatchWithRetry(endpoint, apiKey, payload, timeoutMs, maxRetries = 2, retryDelayMs = 1000) {
  let attempt = 0;
  while (true) {
    attempt += 1;
    try {
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-goog-api-key': apiKey
        },
        body: JSON.stringify(payload),
        signal: AbortSignal.timeout(timeoutMs)
      });

      const rawText = await response.text();
      let body;
      try {
        body = JSON.parse(rawText);
      } catch (_) {
        throw new Error(`Gemini returned non-JSON HTTP ${response.status}: ${rawText}`);
      }

      if (!response.ok) {
        const isTransient = response.status === 429 || response.status >= 500;
        if (isTransient && attempt <= maxRetries) {
          console.warn(`[executor] Transient HTTP ${response.status}. Retrying attempt ${attempt}/${maxRetries} after ${retryDelayMs}ms...`);
          await new Promise(r => setTimeout(r, retryDelayMs * attempt));
          continue;
        }
        throw new Error(`Gemini HTTP ${response.status}: ${JSON.stringify(body.error || body)}`);
      }

      const candidate = body.candidates?.[0]?.content;
      if (!candidate || !Array.isArray(candidate.parts) || candidate.parts.length === 0) {
        throw new Error(`Gemini response contains no candidate parts: ${JSON.stringify(body)}`);
      }
      return candidate;
    } catch (err) {
      if (attempt <= maxRetries && (err.name === 'TimeoutError' || err.code === 'ECONNRESET' || err.name === 'AbortError')) {
        console.warn(`[executor] Network/Timeout error (${err.message}). Retrying attempt ${attempt}/${maxRetries}...`);
        await new Promise(r => setTimeout(r, retryDelayMs * attempt));
        continue;
      }
      throw err;
    }
  }
}

function normalizeTargets(value, seen = new WeakSet()) {
  if (!value || typeof value !== 'object' || seen.has(value)) return;
  seen.add(value);
  if (Array.isArray(value)) {
    for (const item of value) normalizeTargets(item, seen);
    return;
  }
  for (const [key, child] of Object.entries(value)) {
    if (targetKeys.has(key) && child === true) {
      value[key] = false;
    } else {
      normalizeTargets(child, seen);
    }
  }
}

function parseJsonArchive(archiveRelativePath) {
  const absolute = resolveRepoFile(archiveRelativePath);
  if (!fs.existsSync(absolute) || !fs.statSync(absolute).isFile()) throw new Error(`Complete batch archive does not exist: ${archiveRelativePath}`);
  const lower = archiveRelativePath.toLowerCase();
  let text;

  if (lower.endsWith('.zip')) {
    const listing = execFileSync('unzip', ['-Z1', absolute], { encoding: 'utf8' })
      .split(/\r?\n/).filter(Boolean).filter(name => name.toLowerCase().endsWith('.json'));
    if (listing.length !== 1) throw new Error('ZIP solution must contain exactly one JSON file.');
    text = execFileSync('unzip', ['-p', absolute, listing[0]], { encoding: 'utf8', maxBuffer: 100 * 1024 * 1024 });
  } else if (lower.endsWith('.tar.gz') || lower.endsWith('.tgz')) {
    const listing = execFileSync('tar', ['-tzf', absolute], { encoding: 'utf8' })
      .split(/\r?\n/).filter(Boolean).filter(name => name.toLowerCase().endsWith('.json'));
    if (listing.length !== 1) throw new Error('TAR.GZ solution must contain exactly one JSON file.');
    text = execFileSync('tar', ['-xOzf', absolute, listing[0]], { encoding: 'utf8', maxBuffer: 100 * 1024 * 1024 });
  } else if (lower.endsWith('.gz')) {
    text = zlib.gunzipSync(fs.readFileSync(absolute)).toString('utf8');
  } else {
    text = fs.readFileSync(absolute, 'utf8');
  }

  return JSON.parse(text);
}

function resolveRepoFile(relativePath) {
  if (typeof relativePath !== 'string' || relativePath.trim() === '') throw new Error('Expected a non-empty repository-relative filename.');
  const resolved = path.resolve(repoRoot, relativePath);
  const prefix = `${repoRoot}${path.sep}`;
  if (resolved !== repoRoot && !resolved.startsWith(prefix)) throw new Error(`Path escapes repository root: ${relativePath}`);
  return resolved;
}

function parseChallengePath(challengePath) {
  const normalized = challengePath.replace(/\\/g, '/');
  const prefix = 'ChatMachines/GeminiSupervisor/live-ground-truth/reading-room/';
  if (!normalized.startsWith(prefix)) throw new Error('Challenge path is outside the reading room');
  const name = path.posix.basename(normalized);
  const match = ACTIVE_RE.exec(name);
  if (!match) throw new Error(`Not an active Live Ground Truth challenge: ${name}`);
  return { challengeCommitSha: match[1].toLowerCase() };
}

async function buildChallenge(commitSha) {
  const sha = validateCommitSha(commitSha);
  const full = projectAgents();
  const canonical = full.items;
  const shuffled = shuffle(canonical);

  if (canonical.length % ROWS !== 0) throw new Error('Canonical item count must fill whole ordered cards');
  const referenceCardCount = canonical.length / ROWS;
  const referenceGroups = [];
  for (let i = 0; i < canonical.length; i += ROWS) {
    referenceGroups.push(canonical.slice(i, i + ROWS));
  }

  const pairs = canonical.map((ordered, i) => ({ ordered, shuffled: shuffled[i] }));
  const pairsPerMixedCard = ROWS / 2;
  const mixedCardCount = referenceCardCount * 2;
  const mixedGroups = [];
  for (let i = 0; i < pairs.length; i += pairsPerMixedCard) {
    mixedGroups.push(pairs.slice(i, i + pairsPerMixedCard));
  }
  if (mixedGroups.length !== mixedCardCount) {
    throw new Error(`Expected ${mixedCardCount} mixed cards, got ${mixedGroups.length}`);
  }

  fs.mkdirSync(readingRoom, { recursive: true });
  removeGeneratedCards();
  removeLegacyCanonical();
  removeActiveChallenges();

  const cards = {};

  for (const group of referenceGroups) {
    const { fileName, pngSha256 } = await writeCard(group);
    cards[fileName] = {
      role: 'ordered-reference',
      slots: group,
      placement_slots: Array(group.length).fill(false),
      png_sha256: pngSha256
    };
  }

  for (const group of mixedGroups) {
    const orderedParity = crypto.randomInt(0, 2) === 0 ? 'odd' : 'even';
    const { slots, placementSlots } = buildMixedSlots(group, orderedParity);
    const { fileName, pngSha256 } = await writeCard(slots);
    cards[fileName] = {
      role: 'mixed',
      ordered_parity: orderedParity,
      slots,
      placement_slots: placementSlots,
      png_sha256: pngSha256
    };
  }

  fs.mkdirSync(manifestRoot, { recursive: true });
  writeJson(manifestPath(sha), {
    challenge: 'agents-png-locator-v2',
    challenge_commit_sha: sha,
    source_blob_sha: full.source_blob_sha,
