function selectedProjection(conversation, limits) {
  const mapping = conversation.mapping;
  const current = conversation.current_node;
  if (!object(mapping) || typeof current !== "string" || !current)
    fail("MISSING_BRANCH", "selected branch requires mapping and current_node");
  const visited = new Set(), chain = [];
  let cursor = current;
  while (cursor !== null) {
    if (chain.length >= limits.ancestry) fail("ANCESTRY_LIMIT", "selected ancestry exceeds limit");
    if (visited.has(cursor)) fail("CYCLIC_PARENT", "selected branch parent cycle");
    visited.add(cursor);
    if (!own(mapping, cursor) || !object(mapping[cursor])) fail("MISSING_PARENT", "missing selected branch node: " + cursor);
    const node = mapping[cursor];
    chain.push({id:cursor,node});
    const parent = node.parent;
    if (parent !== null && parent !== undefined && typeof parent !== "string")
      fail("INVALID_PARENT", "parent link is not a string or null");
    cursor = parent ?? null;
  }
  chain.reverse();
  const counts = {user:0, commentary:0, final:0};
  const messages = [], included_ids = [];
  for (const {id,node} of chain) {
    const m = node.message;
    if (!object(m)) continue;
    const role = m.author?.role, channel = m.channel ?? null;
    if (role !== "user" && !(role === "assistant" && (channel === "commentary" || channel === "final"))) continue;
    const text = textParts(m);
    if (text === null) continue;
    const kind = role === "user" ? "user" : channel;
    counts[kind]++;
    included_ids.push(id);
    messages.push({role, channel:role === "user" ? null : channel, text});
  }
  if (!counts.user || !counts.final) fail("INCOMPLETE_BRANCH", "selected branch requires user and assistant final text");
  return { messages, counts, included_ids, ancestry_ids:chain.map(x => x.id), ancestry_nodes:chain.length };
}

function textParts(message) {
  const parts = message && message.content && message.content.parts;
  if (!Array.isArray(parts)) return null;
  const pieces = parts.filter(p => typeof p === "string");
  if (!pieces.length) return null;
  const result = pieces.join("\n").trimEnd();
  return result.trim() ? result : null;
}

function linearProjection(conversation) {
  const source = conversation.linear_conversation;
  if (!Array.isArray(source) || source.length === 0)
    fail("MISSING_LINEAR", "complete export requires a nonempty linear_conversation array");
  const duplicateIds = [], seenIds = new Set();
  const records = source.map((raw_node, index) => {
    const good = object(raw_node);
    const message = good && object(raw_node.message) ? raw_node.message : null;
    const node_id = good && typeof raw_node.id === "string" ? raw_node.id : null;
    if (node_id !== null) { if (seenIds.has(node_id)) duplicateIds.push(node_id); seenIds.add(node_id); }
    return {
      index, node_id,
      parent:good && typeof raw_node.parent === "string" ? raw_node.parent : null,
      record_kind:!good ? "malformed" : message ? "message" : "no_message",
      role:message && typeof message.author?.role === "string" ? message.author.role : null,
      author_name:message && typeof message.author?.name === "string" ? message.author.name : null,
      channel:message && typeof message.channel === "string" ? message.channel : null,
      recipient:message && typeof message.recipient === "string" ? message.recipient : null,
      create_time: message?.create_time ?? null,
      update_time: message?.update_time ?? null,
      content_type:message && typeof message.content?.content_type === "string" ? message.content.content_type : null,
      status:message && typeof message.status === "string" ? message.status : null,
      end_turn:message?.end_turn ?? null,
      model_slug:message && typeof message.metadata?.model_slug === "string" ? message.metadata.model_slug : null,
      derived_text:message ? textParts(message) : null,
      raw_node
    };
  });
  return {records, source_node_count:records.length,
    message_count:records.filter(r => r.record_kind === "message").length,
    duplicate_ids:duplicateIds};
}

function validateDestinationTemplate(template, context) {
  const source = nonemptyString(template, "write_path", 240);
  if (source.startsWith("/") || source.includes("\\") || source.includes("//") || source.endsWith("/")) {
    fail("INVALID_WRITE_PATH", "write_path must be a normalized repository-relative POSIX path");
  }
  // Allow exactly the two declared template tokens; no substitutions using eval.
  const unknownTemplate = source.replaceAll("{share_uuid}", "").replaceAll("{run_id}", "");
  if (/[{}]/.test(unknownTemplate)) fail("INVALID_WRITE_PATH", "write_path has an unknown template placeholder");
  if (!source.split("/").some(segment => segment === "{run_id}" || segment === context.run_id)) {
    fail("NOT_RUN_ISOLATED", "write_path must contain a complete {run_id} path segment (or the current run ID)");
  }
  const resolved = source.replaceAll("{share_uuid}", context.share_uuid).replaceAll("{run_id}", context.run_id);
  const components = resolved.split("/");
  if (!components.every(part => SEGMENT.test(part) && part !== "." && part !== "..")) {
    fail("INVALID_WRITE_PATH", "write_path contains invalid or traversal path segments");
  }
  if (components.length < 4 || components[0] !== "workspaces" ||
      components[1] !== "chatgpt-linear-exports") {
    fail("WRITE_PATH_OUT_OF_SCOPE", `write_path must be within ${OUTPUT_ROOT}/ and include a run-specific subdirectory`);
  }
  if (resolved.length > 240 || path.posix.normalize(resolved) !== resolved) {
    fail("INVALID_WRITE_PATH", "expanded write_path is invalid or exceeds 240 characters");
  }
  return { write_path_template: source, write_path: resolved };
}

function assertSafeFilesystem(repoRoot, writePath, shareId) {
  const root = path.resolve(repoRoot);
  const dest = path.resolve(root, writePath);
  const relative = path.relative(root, dest);
  if (!relative || relative.startsWith(".." + path.sep) || relative === ".." || path.isAbsolute(relative)) {
    invalid("WRITE_PATH_OUTSIDE_WORKSPACE", "resolved destination escapes repository root");
  }

  let cursor = root;
  for (const segment of writePath.split("/")) {
    cursor = path.join(cursor, segment);
    const entry = fs.lstatSync(cursor, {throwIfNoEntry: false});
    if (entry?.isSymbolicLink()) {
      invalid("WRITE_PATH_SYMLINK", `symlink in destination ancestry: ${path.relative(root, cursor)}`);
    }
    if (entry && !entry.isDirectory()) {
      invalid("WRITE_PATH_INVALID", `non-directory component: ${path.relative(root, cursor)}`);
    }
  }
  for (const filename of OUTPUT_FILES) {
    const file = path.join(dest, filename);
    const entry = fs.lstatSync(file, {throwIfNoEntry: false});
    if (entry?.isSymbolicLink() || (entry && !entry.isFile())) {
      invalid("WRITE_PATH_INVALID", `unsafe existing output target: ${filename}`);
    }
  }

  // Prevent accidental replacement of another share's transcript. The URL's
  // query does not affect share identity, but a different UUID does.
  const existingJson = path.join(dest, "conversation.json");
  if (fs.existsSync(existingJson)) {
    let existing;
    try {
      existing = JSON.parse(fs.readFileSync(existingJson, "utf8"));
    } catch {
      invalid("WRITE_PATH_COLLISION", "existing conversation.json is unreadable or malformed");
    }
    try {
      const old = parseShareUrl(existing?.source_url);
      if (old.share_id !== shareId) {
        invalid("WRITE_PATH_COLLISION", "destination already belongs to a different shared conversation");
      }
    } catch (err) {
      if (err instanceof InputError && err.code === "WRITE_PATH_COLLISION") throw err;
      invalid("WRITE_PATH_COLLISION", "existing conversation.json lacks valid matching source provenance");
    }
  } else if (fs.existsSync(path.join(dest, "conversation.md"))) {
    invalid("WRITE_PATH_COLLISION", "existing conversation.md has no companion JSON provenance");
  }
}

function parseInputs(input, options = {}) {
  if (!input || typeof input !== "object" || Array.isArray(input) ||
      Object.keys(input).some(key => !["target_url", "write_path"].includes(key))) {
    invalid("INPUT_SCHEMA_INVALID", "input must contain only target_url and optional write_path");
  }
  const parsed = parseShareUrl(input.target_url);
  const writePath = validateDestination(input.write_path, parsed.share_id);
  assertSafeFilesystem(options.repoRoot ?? process.cwd(), writePath, parsed.share_id);
  return Object.freeze({
    schema: "terminals.shared-chat-extractor.inputs.v1",
    target_url: parsed.target_url,
    share_id: parsed.share_id,
    write_path: writePath
  });
}

function encode(root) {
  const table=[];const keys=new Map();
  function keyIndex(k){if(!keys.has(k)){keys.set(k,table.length);table.push(k);}return keys.get(k);}
  function value(v){
    const index=table.length;table.push(null);
    if(Array.isArray(v))table[index]=v.map(value);
    else if(v&&typeof v==="object"){const out={};for(const [k,x] of Object.entries(v))out["_"+keyIndex(k)]=value(x);table[index]=out;}
    else table[index]=v;
    return index;
  }
  value(root);return table;
}

